public static int finalGrade(int year, int exam) {
    return (int) Math.round((year + exam) / 2.0);
}

public static int countExamHigher(int[] years, int[] exams) {
    int count = 0;
    int i = 0;
    while (years[i] != -1 && exams[i] != -1) {
        if (exams[i] > years[i]) {
            count++;
        }
        i++;
    }
    return count;
}

public static int countExamLower(int[] years, int[] exams) {
    int count = 0;
    int i = 0;
    while (years[i] != -1 && exams[i] != -1) {
        if (exams[i] < years[i]) {
            count++;
        }
        i++;
    }
    return count;
}

